export const unknown=v=>!v||['NOASSERTION','NONE'].includes(v);
export function normalize(raw,filename='SBOM'){
 if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Expected an SBOM JSON object.');
 const cdx=raw.bomFormat==='CycloneDX',spdx=typeof raw.spdxVersion==='string';
 if(!cdx&&!spdx)throw Error('Use CycloneDX JSON or SPDX 2.x JSON. SPDX 3 JSON-LD is not supported.');
 if(spdx&&!raw.spdxVersion.startsWith('SPDX-2.'))throw Error('This viewer supports SPDX 2.x JSON.');
 const components=[],edges=[],vulns=[];let seq=0;
 const add=(c,parent)=>{const id=c['bom-ref']||c.SPDXID||`generated-${++seq}`;const licenses=cdx?(c.licenses||[]).map(x=>x.expression||x.license?.id||x.license?.name).filter(Boolean):[c.licenseConcluded&&!unknown(c.licenseConcluded)?c.licenseConcluded:c.licenseDeclared].filter(x=>!unknown(x));const purl=cdx?c.purl:(c.externalRefs||[]).find(x=>x.referenceType==='purl')?.referenceLocator;components.push({id,name:c.name||'(unnamed)',version:c.version||c.versionInfo||'',group:c.group||'',type:c.type||'library',purl:purl||'',licenses,hashes:c.hashes||c.checksums||[],supplier:c.supplier?.name||c.supplier||'',description:c.description||c.summary||'',raw:c});if(parent)edges.push([parent,id]);(c.components||[]).forEach(x=>add(x));return id;};
 let root=null;
 if(cdx){if(raw.metadata?.component)root=add(raw.metadata.component);(raw.components||[]).forEach(x=>add(x));(raw.dependencies||[]).forEach(d=>(d.dependsOn||[]).forEach(t=>edges.push([d.ref,t])));(raw.vulnerabilities||[]).forEach(v=>{const ratings=v.ratings||[];const severity=ratings.map(x=>x.severity).find(x=>x&&x!=='unknown')||'unknown';vulns.push({id:v.id||'Unspecified finding',severity:String(severity).toLowerCase(),score:ratings.find(x=>x.score!=null)?.score,refs:(v.affects||[]).map(x=>x.ref),description:v.description||v.detail||'',state:v.analysis?.state||'not supplied',response:(v.analysis?.response||[]).join(', '),source:v.source?.name||'',url:v.source?.url||'',raw:v});});}
 else{(raw.packages||[]).forEach(x=>add(x));(raw.relationships||[]).forEach(r=>{if(r.relationshipType==='DEPENDS_ON')edges.push([r.spdxElementId,r.relatedSpdxElement]);if(r.relationshipType==='DEPENDENCY_OF')edges.push([r.relatedSpdxElement,r.spdxElementId]);if(r.relationshipType==='DESCRIBES'&&r.spdxElementId===raw.SPDXID)root=r.relatedSpdxElement;});root=root||(raw.documentDescribes||[])[0]||null;}
 const map=new Map();components.forEach(c=>{if(!map.has(c.id))map.set(c.id,c);});const uniqueEdges=[...new Map(edges.map(e=>[JSON.stringify(e),e])).values()];const outgoing=new Map(),incoming=new Map();for(const [a,b]of uniqueEdges){if(!outgoing.has(a))outgoing.set(a,[]);outgoing.get(a).push(b);if(!incoming.has(b))incoming.set(b,[]);incoming.get(b).push(a);}
 const roots=root&&map.has(root)?[root]:components.filter(c=>!(incoming.get(c.id)||[]).length).map(c=>c.id);const depths=new Map(),q=roots.map(x=>[x,0]);for(let i=0;i<q.length;i++){const [id,n]=q[i];if(depths.has(id))continue;depths.set(id,n);for(const t of outgoing.get(id)||[])if(map.has(t))q.push([t,n+1]);}
 const colors=new Map(),cycles=[];for(const start of map.keys()){if(colors.get(start))continue;const stack=[[start,0]];colors.set(start,1);while(stack.length){const top=stack[stack.length-1],children=outgoing.get(top[0])||[];if(top[1]>=children.length){colors.set(top[0],2);stack.pop();continue;}const t=children[top[1]++];if(!map.has(t))continue;if(colors.get(t)===1){if(cycles.length<100)cycles.push([top[0],t]);}else if(!colors.get(t)){colors.set(t,1);stack.push([t,0]);}}}
 const unresolved=uniqueEdges.filter(([a,b])=>!map.has(a)||!map.has(b));const missing=key=>components.filter(c=>key==='licenses'?!c.licenses.length:!c[key]).length;
 return {raw,filename,format:cdx?'CycloneDX':'SPDX',spec:raw.specVersion||raw.spdxVersion,name:map.get(root)?.name||raw.name||filename,version:map.get(root)?.version||'',timestamp:raw.metadata?.timestamp||raw.creationInfo?.created||'',components,map,edges:uniqueEdges,outgoing,incoming,roots,root,depths,cycles,unresolved,vulns,missing,duplicateRefs:components.length-map.size};
}
export function closure(model,id,direction='outgoing'){const seen=new Set(),queue=[id];for(let i=0;i<queue.length;i++)for(const t of model[direction].get(queue[i])||[])if(!seen.has(t)&&t!==id){seen.add(t);queue.push(t);}return [...seen];}
export function pathTo(model,id){const queue=model.roots.map(x=>[x]);const seen=new Set();for(let i=0;i<queue.length;i++){const path=queue[i],n=path.at(-1);if(n===id)return path;if(seen.has(n))continue;seen.add(n);for(const t of model.outgoing.get(n)||[])if(!seen.has(t))queue.push([...path,t]);}return [];}
export function compare(current,baseline){const key=c=>c.purl?c.purl.replace(/@[^/?#]+(?=[?#]|$)/,''):`${c.group}/${c.name}:${c.type}`;const group=m=>{const g=new Map();m.components.forEach(c=>{const k=key(c);if(!g.has(k))g.set(k,[]);g.get(k).push(c)});return g};const a=group(current),b=group(baseline),rows=[];for(const k of new Set([...a.keys(),...b.keys()])){const now=a.get(k)||[],old=b.get(k)||[];const n=now.map(c=>c.version||'(unspecified)').sort().join(', '),o=old.map(c=>c.version||'(unspecified)').sort().join(', ');if(!old.length)rows.push({status:'Added',name:now[0].name,before:'—',after:n});else if(!now.length)rows.push({status:'Removed',name:old[0].name,before:o,after:'—'});else if(n!==o)rows.push({status:'Changed',name:now[0].name,before:o,after:n});else if(JSON.stringify(now.map(c=>c.licenses.join(' OR ')).sort())!==JSON.stringify(old.map(c=>c.licenses.join(' OR ')).sort()))rows.push({status:'License changed',name:now[0].name,before:old.map(c=>c.licenses.join(' OR ')||'Unknown').join(', '),after:now.map(c=>c.licenses.join(' OR ')||'Unknown').join(', ')});}return rows;}
export function sample(){const packages=[['react','18.2.0','MIT'],['react-dom','18.2.0','MIT'],['express','4.18.2','MIT'],['lodash','4.17.20','MIT'],['axios','1.6.0','MIT'],['jsonwebtoken','9.0.0','MIT'],['postgres','3.4.3','Unlicense'],['zod','3.22.4','MIT'],['debug','2.6.9','MIT'],['body-parser','1.20.1','MIT'],['qs','6.11.0','BSD-3-Clause'],['cookie','0.5.0','MIT'],['scheduler','0.23.0','MIT'],['jose','4.15.4','MIT'],['follow-redirects','1.15.3','MIT'],['ms','2.0.0','MIT'],['internal-auth','2.1.0',''],['legacy-parser','1.3.0','GPL-3.0-only']];return {bomFormat:'CycloneDX',specVersion:'1.5',metadata:{timestamp:'2026-10-12T09:30:00Z',component:{'bom-ref':'app',type:'application',name:'atlas-api',version:'2.8.0'}},components:packages.map(([name,version,license])=>({'bom-ref':name,name,version,type:'library',purl:name==='internal-auth'?undefined:`pkg:npm/${name}@${version}`,licenses:license?[{license:{id:license}}]:[]})),dependencies:[['app',['react','react-dom','express','lodash','axios','jsonwebtoken','postgres','zod','internal-auth']],['react-dom',['react','scheduler']],['express',['debug','body-parser','qs','cookie']],['axios',['follow-redirects']],['jsonwebtoken',['jose']],['body-parser',['debug','qs']],['debug',['ms']],['internal-auth',['jsonwebtoken','legacy-parser']]].map(([ref,dependsOn])=>({ref,dependsOn})),vulnerabilities:[{id:'DEMO-HIGH-001',description:'Illustrative prototype-pollution finding. Sample data only; not a live advisory assessment.',ratings:[{severity:'high',score:7.4}],affects:[{ref:'lodash'}],analysis:{state:'in_triage'}},{id:'DEMO-MEDIUM-002',description:'Illustrative redirect-handling finding. Sample data only.',ratings:[{severity:'medium',score:5.3}],affects:[{ref:'follow-redirects'}]}]};}
